      <template v-else>
        <!-- ── LEAVE TYPE SELECTION ──────────────────────────────────── -->
        <section v-if="!selectedLeaveType" class="lr-section">
          <div class="lr-section__head">
            <div class="lr-section__title">
              <v-icon size="20" color="#6366f1" class="mr-2"
