            <!-- Actions -->
            <template #[`item._actions`]="{ item }">
              <div class="lr-table__actions">
                <button
                  class="lr-action-btn lr-action-btn--view"
                  title="View Details"
                  @click="
                    $router.push(
                      `/custom/leave-request-view?path=/lesotho/components/leave&leave=${item.id}`,
                    )
                  "
                >
                  <v-icon size="14" color="#6366f1">mdi-eye</v-icon>
                </button>
                <button
                  v-if="item.status === 'undersupervisorreview'"
                  class="lr-action-btn lr-action-btn--edit"
                  :class="{ 'lr-action-btn--disabled': !isOwner }"
                  :disabled="!isOwner"
                  title="Edit Request"
                  @click="editRequest(item)"
                >
                  <v-icon size="14" color="#f59e0b">mdi-pencil</v-icon>
                </button>
                <button
                  v-if="canCancel(item)"
                  class="lr-action-btn lr-action-btn--cancel"
                  title="Cancel Request"
