<script>
import generalMixin from "../../mixins/general";
export default {
  name: "LeaveRequest",
  mixins: [generalMixin],
  props: ["queries"],
  data() {
    return {
      // supervisors only: how many of their staff are on leave today
      teamOnLeave: { show: false, count: 0 },
      overlay: false,
      snackbar: false,
      loading: true,
      snackbarMessage: "",
      snackbarColor: "success",

      loadingRequests: false,

      // Staff Information
      leaveInfo: {
        financialYear: {},
        id: null,
        salaryGrade: "",
        employmentType: "",
      },

      // Leave Type Selection
      selectedLeaveType: null,
      requestId: null,
      availableLeaveTypes: [
        {
          code: "annual",
          name: "Annual Leave",
          icon: "mdi-beach",
          color: "blue",
          duration: "15-36 days/year",
          description: "Based on salary grade",
          enabled: true,
          balance: null,
          component: "annual-leave-request",
        },
        {
          code: "maternity",
          name: "Maternity Leave",
          icon: "mdi-mother-nurse",
          color: "pink",
          duration: "90 days",
          description: "For female staff",
          enabled: true,
          balance: null,
          component: "maternity-leave-request",
        },
        {
          code: "paternity",
          name: "Paternity Leave",
          icon: "mdi-human-male-child",
          color: "indigo",
          duration: "14 days",
          description: "For male staff",
          enabled: false, // Set based on gender
          balance: null,
          component: "paternity-leave-request",
        },
        {
          code: "compassionate",
          name: "Compassionate Leave",
          icon: "mdi-hand-heart",
          color: "purple",
          duration: "3-5 days",
          description: "Death of family member",
          enabled: true,
          balance: null,
          component: "compassionate-leave-request",
        },
        {
          code: "unpaid",
          name: "Unpaid Leave",
          icon: "mdi-currency-usd-off",
          color: "orange",
          duration: "Up to 3 months",
          description: "Permanent staff only",
          enabled: true, // Set based on employment type
          balance: null,
          component: "unpaid-leave-request",
        },
        {
          code: "sick",
          name: "Sick Leave",
          icon: "mdi-hospital-box",
          color: "red",
          duration: "12 days",
          description: "Medical certificate required",
          enabled: true,
          balance: null,
          component: "sick-leave-request",
        },
        {
          code: "stillborn",
          name: "Still Born/Miscarriage",
          icon: "mdi-heart-broken",
          color: "deep-purple",
          duration: "28 days",
          description: "For female staff",
          enabled: false, // Set based on gender
          balance: null,
          component: "stillborn-leave-request",
        },
        {
          code: "bonding",
          name: "Bonding Leave",
          icon: "mdi-baby-carriage",
          color: "teal",
          duration: "14 days",
          description: "Child adoption",
          enabled: true,
          balance: null,
          component: "bonding-leave-request",
        },
        {
          code: "study",
          name: "Study Leave",
          icon: "mdi-school",
          color: "green",
          duration: "Varies",
          description: "Based on training type",
          enabled: true,
          balance: null,
          component: "study-leave-request",
        },
      ],

      // Leave Requests
      myLeaveRequests: [],
      totalRequests: 0,
      tableOptions: { page: 1, itemsPerPage: 5, sortBy: [], sortDesc: [] },
      tableHeaders: [
        { text: "Leave Type", value: "leaveType", sortable: false },
        { text: "Start Date", value: "startDate", sortable: false },
        { text: "End Date", value: "endDate", sortable: false },
        { text: "Days", value: "totalDays", sortable: false },
        { text: "Status", value: "status", sortable: false },
        { text: "Submitted", value: "submittedDate", sortable: false },
        {
          text: "Actions",
          value: "_actions",
          sortable: false,
          align: "center",
        },
      ],
    };
  },

  computed: {
    isOwner() {
      return this.queries.practitioner === this.loggedInStaff.practitioner;
    },
    selectedLeaveComponent() {
      return this.selectedLeaveType?.component || null;
    },

    breadcrumbs() {
      return [
        {
          text: "Select Leave Type",
          clickable: true,
        },
        {
          text: this.selectedLeaveType?.name || "",
          clickable: false,
        },
      ];
    },
  },

  async mounted() {
    this.loading = true;
    await this.$nextTick();
    await new Promise((r) => setTimeout(r, 400));
    if (!this.queries.practitioner) {
      this.queries.practitioner = this.$store.state.user.obj.resource.extension
        .find((ext) => {
          return (
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/ihris-practitioner-reference"
          );
        })
        ?.valueReference?.reference?.split("/")?.[1];
    }

    // Wait for user data from mixin to be loaded first
    // This ensures staff.gender and other user data is available
    // before we proceed with leave type availability checks
    await this.$nextTick(); // Ensure created hook from mixin has started

    // Wait for getUserDepartment from mixin to complete
    // We watch loadingUserData which is set to false when getUserDepartment completes
    await new Promise((resolve) => {
      if (!this.loadingUserData) {
        // Already loaded
        resolve();
        return;
      }

      // Watch for loadingUserData to become false
      const unwatch = this.$watch("loadingUserData", (newValue) => {
        if (!newValue) {
          unwatch();
          resolve();
        }
      });

      // Timeout after 15 seconds
      setTimeout(() => {
        unwatch();
        console.warn("Timeout waiting for user data to load");
        resolve();
      }, 15000);
    });

    if (!this.loggedInStaff.practitioner) {
      this.$store.commit("setMessage", {
        type: "error",
        text:
          "We are not able to identify you, your account doesnt meet the criteria to request leave",
      });
      setTimeout(() => {
        this.$router.go(-1);
      }, 1000);
    }
    if (this.loggedInStaff.practitioner != this.queries.practitioner) {
      this.$store.commit("setMessage", {
        type: "warning",
        text:
          "You are not the owner of this profile, you cant make request on behalf of " +
          this.practitionerProfile.name,
      });
    }
    // Now proceed with leave-specific loading
    // At this point, staff.gender and userDepartment are available
    if (this.loggedInStaff.practitioner) {
      // runs in the background; the page doesn't wait for it
      this.loadTeamOnLeave();
      let year = await fetch("/site/leave/getFinancialYear");
      year = await year.json();
      this.leaveInfo.financialYear = year;

      await this.updateLeaveTypeAvailability();
      await this.loadLeaveBalances();
      await this.loadMyLeaveRequests();
    }

    this.loading = false;
  },

  watch: {
    tableOptions: {
      handler() {
        if (this.queries.practitioner) {
          this.loadMyLeaveRequests();
        }
      },
      deep: true,
    },
  },

  methods: {
    // Shows the "Staff on leave" button only to supervisors, with today's count.
    // Uses the logged-in user, not queries.practitioner, since HR can open someone else's page.
    async loadTeamOnLeave() {
      try {
        const response = await fetch(
          `/site/general/supervisee/${this.loggedInStaff.practitioner}`,
        );
        if (!response.ok) return;
        const supervisees = (await response.json()) || [];
        const ids = [...new Set(supervisees.map((s) => s.id).filter(Boolean))];
        if (!ids.length) return;
        this.teamOnLeave.show = true;

        const today = this.$moment().format("YYYY-MM-DD");
        let count = 0;
        // batches keep each URL a sensible length for large teams
        for (let i = 0; i < ids.length; i += 40) {
          const params = new URLSearchParams({
            _profile:
              "http://ihris.org/fhir/StructureDefinition/leave-request-profile",
            practitioner: ids
              .slice(i, i + 40)
              .map((id) => `Practitioner/${id}`)
              .join(","),
            requeststatus: "approved,recalled",
            startdate: `le${today}`,
            enddate: `ge${today}`,
            _summary: "count",
          });
          const result = await fetch(`/fhir/Basic?${params.toString()}`);
          if (result.ok) count += (await result.json()).total || 0;
        }
        this.teamOnLeave.count = count;
      } catch (error) {
        // the button is a convenience; never let it break the page
        console.error("Error loading staff on leave:", error);
      }
    },

    openStaffOnLeave() {
      this.$router.push(
        "/custom/staff-on-leave?path=/lesotho/components/leave",
      );
    },

    canCancel(request) {
      if (
        request.status == "approved" &&
        request.leaveTypeId == "unpaid"
        // && this.$moment().isAfter(request.endDate)
      ) {
        return true;
      }
      return false;
    },
    updateLeaveTypeAvailability() {
      this.availableLeaveTypes.forEach((leaveType) => {
        switch (leaveType.code) {
          case "maternity":
            leaveType.enabled =
              this.loggedInStaff.gender === "female" && this.isOwner;
            break;
          case "stillborn":
            leaveType.enabled =
              this.loggedInStaff.gender === "female" && this.isOwner;
            break;
          case "paternity":
            leaveType.enabled =
              this.loggedInStaff.gender === "male" && this.isOwner;
            break;
          case "unpaid":
            leaveType.enabled =
              this.isOwner &&
              this.loggedInStaff.employment_category === "permanent";
            break;
          default:
            leaveType.enabled = this.isOwner;
        }
      });
    },

    async loadLeaveBalances() {
      let leaveDetails = await fetch(
        "/site/leave/leaveDetails/" + this.queries.practitioner,
      );
      leaveDetails = await leaveDetails.json();
      const balances = {
        annual: 15,
        sick: 12,
      };

      this.availableLeaveTypes.forEach((leaveType) => {
        if (leaveDetails[leaveType.code] !== undefined) {
          leaveType.details = leaveDetails[leaveType.code];
        }
      });

      this.availableLeaveTypes.forEach((leaveType) => {
        if (balances[leaveType.code] !== undefined) {
          leaveType.balance = balances[leaveType.code];
        }
      });
    },

    async loadMyLeaveRequests() {
      this.loadingRequests = true;
      try {
        const { page, itemsPerPage } = this.tableOptions;
        const count = itemsPerPage > 0 ? itemsPerPage : 10;
        const offset = (page - 1) * count;

        // Step 1: fetch IDs only (no includes) from offset 0 to avoid HAPI pagination race
        const idParams = new URLSearchParams({
          _profile:
            "http://ihris.org/fhir/StructureDefinition/leave-request-profile",
          practitioner: `Practitioner/${this.queries.practitioner}`,
          _sort: "-_lastUpdated",
          _count: String(offset + count),
          _getpagesoffset: "0",
          _total: "accurate",
          _elements: "id",
        });
        const idResponse = await fetch(`/fhir/Basic?${idParams}`);
        if (!idResponse.ok) throw new Error("Failed to load leave requests");
        const idBundle = await idResponse.json();

        this.totalRequests = idBundle.total || 0;
        this.myLeaveRequests = [];

        const allIds = (idBundle.entry || []).map((e) => e.resource.id);
        const pageIds = allIds.slice(offset, offset + count);

        if (pageIds.length === 0) return;

        // Step 2: fetch full details + includes for just this page's IDs
        const detailParams = new URLSearchParams({
          _id: pageIds.join(","),
          _include: "Basic:leavecategory",
          _revinclude: "Basic:leaverequest",
        });
        const detailResponse = await fetch(`/fhir/Basic?${detailParams}`);
        if (!detailResponse.ok)
          throw new Error("Failed to load leave request details");
        const results = await detailResponse.json();

        if (results.entry && results.entry.length > 0) {
          for (const id of pageIds) {
            const entry = results.entry.find(
              (e) =>
                e.resource.id === id &&
                e.resource.meta?.profile?.includes(
                  "http://ihris.org/fhir/StructureDefinition/leave-request-profile",
                ),
            );
            if (!entry) continue;
            let resource = entry.resource;
            if (
              !resource.meta.profile.includes(
                "http://ihris.org/fhir/StructureDefinition/leave-request-profile",
              )
            ) {
              continue;
            }
            let categoryResource = results.entry.find((ent) => {
              return (
                ent.resource.id ===
                resource.extension
                  .find((ext) => {
                    return (
                      ext.url ===
                      "http://ihris.org/fhir/StructureDefinition/leave-category"
                    );
                  })
                  ?.valueReference?.reference?.split("/")[1]
              );
            })?.resource;
            const request = {
              id: resource.id,
              leaveType: categoryResource?.extension?.find((ext) => {
                return (
                  ext.url ===
                  "http://ihris.org/fhir/StructureDefinition/ihris-basic-name"
                );
              })?.valueString,
              leaveTypeId: categoryResource?.id,
              startDate: this.getExtensionValue(
                resource,
                "http://ihris.org/fhir/StructureDefinition/start-date",
                "valueDate",
              ),
              endDate: this.getExtensionValue(
                resource,
                "http://ihris.org/fhir/StructureDefinition/end-date",
                "valueDate",
              ),
              totalDays:
                this.getExtensionValue(
                  resource,
                  "http://ihris.org/fhir/StructureDefinition/leave-days",
                  "valueInteger",
                ) || 0,
              status: this.getExtensionValue(
                resource,
                "http://ihris.org/fhir/StructureDefinition/request-status",
                "valueCoding",
              )?.code,
              statusDisplay:
                this.getExtensionValue(
                  resource,
                  "http://ihris.org/fhir/StructureDefinition/request-status",
                  "valueCoding",
                )?.display || "Unknown",
              submittedDate: resource.meta?.lastUpdated,
            };

            const studyLeave = results.entry.find((ent) => {
              return (
                ent.resource.meta.profile.includes(
                  "http://ihris.org/fhir/StructureDefinition/study-leave-profile",
                ) &&
                ent.resource.extension?.some((ext) => {
                  return (
                    ext.url ===
                      "http://ihris.org/fhir/StructureDefinition/leave-request-reference" &&
                    ext.valueReference?.reference === `Basic/${resource.id}`
                  );
                })
              );
            })?.resource;
            if (studyLeave) {
              request.qualification = await this.resolveQualificationName(
                studyLeave,
              );
            }

            this.myLeaveRequests.push(request);
          }
        }
      } catch (error) {
        console.error("Error loading leave requests:", error);
        this.showSnackbar("Error loading leave requests", "error");
      } finally {
        this.loadingRequests = false;
      }
    },
    selectLeaveType(leaveType) {
      if (!leaveType.enabled) {
        this.showSnackbar(
          `${leaveType.name} is not available for you`,
          "warning",
        );
        return;
      }
      this.selectedLeaveType = leaveType;
    },

    changeLeaveType() {
      this.selectedLeaveType = null;
      this.requestId = null;
    },

    async leaveSubmitted() {
      try {
        await this.loadMyLeaveRequests();
        this.selectedLeaveType = null;
        this.requestId = null;
      } catch (error) {
        console.error("Error submitting leave request:", error);
        this.showSnackbar("Error submitting leave request", "error");
      } finally {
        this.overlay = false;
      }
    },

    viewRequest(request) {
      // Navigate to leave request details page
      this.$router.push(`/leave-request/${request.id}`);
    },
    async editRequest(request) {
      if (request.status !== "undersupervisorreview") {
        this.showSnackbar(
          "Only requests in draft or under supervisor review can be edited",
          "warning",
        );
        this.overlay = false;
        return;
      }

      // Find the matching leave type
      const leaveType = this.availableLeaveTypes.find(
        (lt) => lt.code === request.leaveTypeId,
      );

      if (!leaveType) {
        this.showSnackbar("Leave type not found", "error");
        this.overlay = false;
        return;
      }

      // Set the selected leave type and editing resource
      this.selectedLeaveType = leaveType;
      this.requestId = request.id;
    },

    async cancelRequest(request) {
      const leaveType = this.availableLeaveTypes.find(
        (lt) => lt.code === request.leaveTypeId,
      );

      if (!leaveType) {
        this.showSnackbar("Leave type not found", "error");
        this.overlay = false;
        return;
      }

      // Set the selected leave type and editing resource
      this.selectedLeaveType = leaveType;
      this.selectedLeaveType.component = this.selectedLeaveType.component.replace(
        "-request",
        "-cancel",
      );
      this.requestId = request.id;
    },

    getPersonName(person) {
      if (!person.name || person.name.length === 0) return "Unknown";
      const name = person.name[0];
      let fullName = "";
      if (name.given?.length) {
        fullName = name.given.join(" ");
      }
      if (name.family) {
        fullName += " " + name.family;
      }
      return fullName.trim() || "Unknown";
    },

    getExtensionValue(resource, url, type) {
      const extension = resource.extension?.find((ext) => ext.url === url);
      return extension ? extension[type] : null;
    },

    async resolveQualificationName(resource) {
      const qualNameOtherExt = resource.extension?.find((e) =>
        e.url.endsWith("/qualification-name-other"),
      );
      if (qualNameOtherExt?.valueString) return qualNameOtherExt.valueString;

      const qualNameExt = resource.extension?.find((e) =>
        e.url.endsWith("/qualification-name"),
      );
      if (qualNameExt?.valueReference?.display) {
        return qualNameExt.valueReference.display;
      }

      const ref = qualNameExt?.valueReference?.reference;
      if (!ref) return null;

      try {
        const id = ref.split("/")[1];
        const response = await fetch(`/fhir/Basic/${id}`);
        if (!response.ok) return null;

        const qualification = await response.json();
        return qualification.extension?.find((e) =>
          e.url.endsWith("/ihris-basic-name"),
        )?.valueString;
      } catch (error) {
        console.error("Error resolving qualification name:", error);
        return null;
      }
    },

    formatDate(dateString) {
      if (!dateString) return "N/A";
      const date = new Date(dateString);
      return date.toLocaleDateString("en-US", {
        year: "numeric",
        month: "short",
        day: "numeric",
      });
    },

    getBalanceColor(balance) {
      if (balance > 10) return "green";
      if (balance > 5) return "orange";
      return "red";
    },

    getLeaveTypeColor(leaveTypeId) {
      const typeMap = {
        annual: "blue",
        maternity: "pink",
        paternity: "indigo",
        compassionate: "purple",
        unpaid: "orange",
        sick: "red",
        stillborn: "deep-purple",
        bonding: "teal",
        study: "green",
      };
      return typeMap[leaveTypeId] || "grey";
    },

    getStatusColor(status) {
      const statusMap = {
        pending: "blue-grey",
        approved: "green",
        rejected: "red",
        supervisorrejected: "deep-orange",
        hodrejected: "deep-orange darken-1",
        hrrejected: "deep-orange darken-2",
        psrejected: "deep-orange darken-3",
        cancelled: "grey",
        recalled: "amber darken-3",
        undersupervisorreview: "light-blue",
        underhodreview: "blue",
        underhrreview: "indigo",
        underpsreview: "purple",
      };
      return statusMap[status] || "grey";
    },

    showSnackbar(message, color) {
      this.snackbarMessage = message;
      this.snackbarColor = color;
      this.snackbar = true;
    },

    goBack() {
      this.$router.go(-1);
    },

    // ── Display helpers (no business logic) ─────────────────────────────
    getLeaveHexColor(code) {
      const map = {
        annual: "#1e40af",
        maternity: "#db2777",
        paternity: "#4f46e5",
        compassionate: "#7c3aed",
        unpaid: "#f97316",
        sick: "#ef4444",
        stillborn: "#6d28d9",
        bonding: "#0d9488",
        study: "#059669",
      };
      return map[code] || "#6b7280";
    },

    getLeaveTypeIcon(code) {
      const map = {
        annual: "mdi-beach",
        maternity: "mdi-mother-nurse",
        paternity: "mdi-human-male-child",
        compassionate: "mdi-hand-heart",
        unpaid: "mdi-currency-usd-off",
        sick: "mdi-hospital-box",
        stillborn: "mdi-heart-broken",
        bonding: "mdi-baby-carriage",
        study: "mdi-school",
      };
      return map[code] || "mdi-calendar";
    },

    getLeaveTypePillStyle(code) {
      const hex = this.getLeaveHexColor(code);
      return {
        background: hex + "18",
        border: `1px solid ${hex}44`,
        color: hex,
      };
    },
  },

  components: {
    "annual-leave-request": () => import("./annual-leave-request"),
    "maternity-leave-request": () => import("./maternity-leave-request"),
    "paternity-leave-request": () => import("./paternity-leave-request"),
    "stillborn-leave-request": () => import("./stillborn-leave-request"),
    "compassionate-leave-request": () =>
      import("./compassionate-leave-request"),
    "bonding-leave-request": () => import("./bonding-leave-request"),
    "sick-leave-request": () => import("./sick-leave-request"),
    "unpaid-leave-request": () => import("./unpaid-leave-request"),
    "unpaid-leave-cancel": () => import("./unpaid-leave-cancel"),
    "study-leave-request": () => import("./study-leave-request"),
  },
};
</script>

